-- READ-ONLY six-archive cohort summary; SELECT only.
SELECT 'wh1080' AS archive,3 AS gap_count,COUNT(DISTINCT gap_id) AS gaps_with_rows,3-COUNT(DISTINCT gap_id) AS gaps_without_rows,COUNT(*) AS source_rows,COUNT(DISTINCT CASE WHEN `outTemp` IS NOT NULL THEN gap_id END) AS gaps_with_outTemp, SUM(`outTemp` IS NOT NULL) AS values_outTemp, COUNT(DISTINCT CASE WHEN `outHumidity` IS NOT NULL THEN gap_id END) AS gaps_with_outHumidity, SUM(`outHumidity` IS NOT NULL) AS values_outHumidity, COUNT(DISTINCT CASE WHEN `rain` IS NOT NULL THEN gap_id END) AS gaps_with_rain, SUM(`rain` IS NOT NULL) AS values_rain, COUNT(DISTINCT CASE WHEN `rainRate` IS NOT NULL THEN gap_id END) AS gaps_with_rainRate, SUM(`rainRate` IS NOT NULL) AS values_rainRate, COUNT(DISTINCT CASE WHEN `windSpeed` IS NOT NULL THEN gap_id END) AS gaps_with_windSpeed, SUM(`windSpeed` IS NOT NULL) AS values_windSpeed, COUNT(DISTINCT CASE WHEN `windGust` IS NOT NULL THEN gap_id END) AS gaps_with_windGust, SUM(`windGust` IS NOT NULL) AS values_windGust, COUNT(DISTINCT CASE WHEN `barometer` IS NOT NULL THEN gap_id END) AS gaps_with_barometer, SUM(`barometer` IS NOT NULL) AS values_barometer FROM (SELECT CASE WHEN `dateTime`>1685274900 AND `dateTime`<1685332200 THEN 1 WHEN `dateTime`>1697018100 AND `dateTime`<1697025000 THEN 2 WHEN `dateTime`>1699510500 AND `dateTime`<1699561200 THEN 3 ELSE NULL END AS gap_id,`dateTime`,`outTemp`,`outHumidity`,`rain`,`rainRate`,`windSpeed`,`windGust`,`barometer` FROM `weewx_WH1080`.`archive` WHERE (`dateTime`>1685274900 AND `dateTime`<1685332200) OR (`dateTime`>1697018100 AND `dateTime`<1697025000) OR (`dateTime`>1699510500 AND `dateTime`<1699561200)) q;
